	'smp_card_hint' => 'مستخدمون ومستويات وصول ونماذج بكل أنواع الكائنات – للتجربة والاختبار. كل شيء يبدأ بـ sample_.',
	'smp_intro' => 'يثبّت تطبيقًا نموذجيًا صغيرًا: 5 مستخدمين بـ 5 مستويات وصول، ونماذج للعملاء والمنتجات والطلبات، ونموذجًا واحدًا بكل أنواع الكائنات والتنسيقات. كل سجل وجدول ومعرّف يبدأ بـ sample_، لذا يمكن إزالته بالكامل. النماذج مكتوبة بصيغة nuBuilder وتفتح في nuBuilder أيضًا. ويتضمن أيضًا أربع لوحات معلومات: في صفحة بداية المستخدمين النموذجيين وفي نموذج العملاء (علامة التبويب Statistics) وفي نموذج البداية النموذجي.',
	'smp_intro_home' => 'صفحات البداية للمستخدمين: يحصل sample_sales (داريو) على مكتب مبيعات مع المفضلة ومجموعة لصلاحية sample_discount فقط، وsample_manager (كارلا) على صفحة بعلامتي تبويب ومجموعة لفريق Lead فقط، وsample_editor (بن) على قائمة إدخال مع تقرير لبعض المناصب فقط. يحتفظ sample_viewer وsample_secure بالصفحة التلقائية بنماذجهما وتقاريرهما.',
