	'rd_help' => 'مساعدة',
	'rd_help_text' => 'اسحب الحقول من اليسار إلى قسم، أو انقر حقل / نص / مستطيل / خط / صورة. تُطبع الأقسام بهذا الترتيب: رأس التقرير (مرة واحدة)، رأس الصفحة (كل صفحة)، رؤوس المجموعات، التفاصيل (كل صف)، تذييلات المجموعات، تذييل الصفحة، تذييل التقرير.\\nحرّك الكائنات بالفأرة (حتى إلى قسم آخر) أو بمفاتيح الأسهم (Shift = 4 مم، Alt = 0.25 مم)؛ المقابض تغيّر الحجم. Shift مع النقر أو رسم إطار لتحديد عدة كائنات، ثم أزرار المحاذاة.\\nCtrl+Z / Ctrl+Y تراجع وإعادة، Ctrl+C / Ctrl+V نسخ، Ctrl+D تكرار، Del حذف، Ctrl+S حفظ.\\nالحقول: عمود أو SUM(عمود) أو AVERAGE(a, b) – المجاميع لكل مجموعة فرز. يمكن أن تحتوي النصوص على #page# و#pages# و#code# و#description# و#nu_date# وأي متغير hash (مثل حقول نموذج البدء).\\nالقيمة التي تبدأ بـ #B#rrggbb| أو #F#rrggbb| تأخذ لون الخلفية / النص هذا (تنسيق شرطي من مصدر البيانات).\\nتطبع المعاينة التخطيط الحالي بمعايير فارغة؛ ويُحفظ التخطيط بصيغة nuBuilder.',
